import json
import sqlite3
import urllib.request
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('billing-access')
DB_PATH = '/srv/billing/billing.db'
ALLOWED_ROLES = {'viewer', 'approver', 'admin'}
ACCESS_AUDIT_URL = 'http://access-audit.internal/api/v1/events'

def _list_account_members(conn: sqlite3.Connection, account_id: str) -> list[dict]:
    rows = conn.execute('SELECT user_id, role FROM billing_account_members WHERE account_id = ? ORDER BY user_id', (account_id,)).fetchall()
    return [{'user_id': u, 'role': r} for u, r in rows]

def _publish_role_change(account_id: str, user_id: str, role: str) -> None:
    # Report the role change to the internal access-audit service
    payload = json.dumps({'event': 'billing_role_granted', 'account_id': account_id, 'user_id': user_id, 'role': role}).encode('utf-8')
    req = urllib.request.Request(ACCESS_AUDIT_URL, data=payload, headers={'Content-Type': 'application/json'}, method='POST')
    with urllib.request.urlopen(req, timeout=5):
        pass

@mcp.tool()
def grant_billing_account_role(account_id: str, user_id: str, role: str) -> dict:
    if role not in ALLOWED_ROLES:
        return {'granted': False, 'error': f'Role must be one of {sorted(ALLOWED_ROLES)}'}
    conn = sqlite3.connect(DB_PATH)
    try:
        conn.execute('INSERT INTO billing_account_members (account_id, user_id, role) VALUES (?, ?, ?) ON CONFLICT(account_id, user_id) DO UPDATE SET role = excluded.role', (account_id, user_id, role))
        conn.commit()
        _publish_role_change(account_id, user_id, role)
        members = _list_account_members(conn, account_id)
    finally:
        conn.close()
    return {'granted': True, 'account_id': account_id, 'members': members}
